const rows = $input.all().map(item => item.json);

// Fixed reference date, matching data/generate_inventory.py's AS_OF convention
// so this workflow's output is deterministic and doesn't drift with real time.
const AS_OF = new Date('2026-08-26T00:00:00Z');

function daysSince(dateStr) {
  if (!dateStr) return Infinity;
  const d = new Date(dateStr + 'T00:00:00Z');
  return Math.floor((AS_OF - d) / (1000 * 60 * 60 * 24));
}

const targetRoles = new Set(['Privileged', 'Admin']);
const inScope = rows.filter(r => targetRoles.has(r.role_category));
const stale = inScope.filter(r => daysSince(r.last_access_review_date) > 90);

let autoAttested = 0;
let flaggedForRemoval = 0;
const flaggedIds = [];

for (const r of stale) {
  if (r.status === 'Active' && r.okta_status === 'Active') {
    autoAttested++;
  } else {
    // Deterministic rule: anything not (Active status + Active in Okta) is
    // not auto-attested. Some of these (e.g. Terminated + already
    // Deprovisioned) have nothing left to remove -- they're flagged here
    // as "not auto-attested" rather than implying pending removal action
    // on an account that's already correctly offboarded.
    flaggedForRemoval++;
    flaggedIds.push(r.employee_id);
  }
}

const today = '2026-08-26';
const observationLine = `[${today}] Automated UAR run (n8n): ${inScope.length} privileged/admin accounts in scope, ${stale.length} due for review (last_access_review_date blank or >90 days old). ${autoAttested} auto-attested (Active in HRIS and Okta, access confirmed still needed). ${flaggedForRemoval} not auto-attested, flagged for manual review (terminated and/or Okta status mismatch): ${flaggedIds.join(', ') || 'none'}.`;

return [{
  json: {
    inScopeCount: inScope.length,
    staleCount: stale.length,
    autoAttestedCount: autoAttested,
    flaggedCount: flaggedForRemoval,
    flaggedIds,
    observationLine,
    escalate: flaggedForRemoval > 0
  }
}];

const computed = $('Filter & Attest UAR').first().json;
const currentFinding = $json;

// Finding.severity is a SmallIntegerField on the model (IntegerChoices);
// the read serializer hydrates it to its display label (e.g. "medium"),
// but the write serializer expects the raw integer back. Map both ways.
const SEVERITY_TO_INT = { undefined: -1, info: 0, low: 1, medium: 2, high: 3, critical: 4 };

const existingObservation = currentFinding.observation || '';
const mergedObservation = existingObservation
  ? existingObservation + '\n' + computed.observationLine
  : computed.observationLine;

let newSeverityLabel = currentFinding.severity;
let escalationLine = '';

if (computed.escalate && currentFinding.severity !== 'high' && currentFinding.severity !== 'critical') {
  newSeverityLabel = 'high';
  escalationLine = `\n[2026-08-26] ESCALATED: severity raised from '${currentFinding.severity}' to 'high' because ${computed.flaggedCount} account(s) were not auto-attested and require manual removal review.`;
}

const finalObservation = mergedObservation + escalationLine;

return [{
  json: {
    findingId: currentFinding.id,
    finalObservation,
    newSeverity: SEVERITY_TO_INT[newSeverityLabel],
    escalated: escalationLine !== ''
  }
}];
